/**
 * Chat session titles generated by the sub-agent model.
 *
 * `deriveSessionTitle` (chatHints) stays the instant, offline title — the sidebar
 * must never be empty and no new chat should wait on the network for a name. This
 * module upgrades that placeholder once, after the first completed turn, with a
 * single tool-free sub-agent call: same shape as the nested coding explore call, so
 * the model is whatever Options has configured for the sub-agent coding role.
 */

import type { UiMessage } from '@/types/chat'
import { deriveSessionTitle, sanitizeForTts } from '@/lib/chatHints'
import type { SubAgentConfig } from '@/lib/settings'
import { callSubAgentChat, type SubAgentKeys } from '@/lib/subAgent'

/** Sidebar width cap; longer titles just get ellipsized by CSS. */
const TITLE_MAX_CHARS = 60
/** A title that needs 12 words is a summary, not a title. */
const TITLE_MAX_WORDS = 12
/**
 * A title is ~6 tokens, but the cap is deliberately generous: a provider that opens a
 * hidden thinking block against a tight cap returns an EMPTY content string (the trap
 * SUB_AGENT_DEFAULT_OUTPUT_TOKENS documents), which looks exactly like "never ran".
 * Brevity is enforced by the sanitizer, not by the token cap.
 */
const TITLE_MAX_OUTPUT_TOKENS = 512
/** Assistant head fed as seed: enough to name the topic, cheap to send. */
const SEED_ASSISTANT_CHARS = 300
const SEED_USER_CHARS = 800

export const TITLE_SYSTEM_PROMPT = [
  'You name chat sessions.',
  'Read the exchange and answer with ONE short topic title, at most 6 words.',
  'Write it in the same language the user wrote in.',
  'Reply with the title alone: no quotes, no markdown, no trailing period, no preamble.',
].join(' ')

/**
 * The first user message + the head of the first assistant reply, sanitized the same
 * way TTS text is (code blocks and URLs are noise for naming). Null when there is no
 * user turn yet — nothing to name.
 */
export function buildTitleSeedText(messages: UiMessage[]): string | null {
  const firstUser = messages.find((m) => m.role === 'user')
  const fallback = firstUser?.images?.length
    ? '[user attached an image]'
    : firstUser?.fileAttachments?.length
      ? `[user attached ${firstUser.fileAttachments[0].name}]`
      : ''
  const userText = sanitizeForTts(firstUser?.content ?? '').slice(0, SEED_USER_CHARS) || fallback
  if (!userText) return null
  const firstAssistant = messages.find((m) => m.role === 'assistant' && m.content.trim())
  const assistantHead = firstAssistant
    ? sanitizeForTts(firstAssistant.content).slice(0, SEED_ASSISTANT_CHARS)
    : ''
  return assistantHead ? `User: ${userText}\n\nAssistant: ${assistantHead}` : `User: ${userText}`
}

/**
 * Models decorate titles: quotes, a "Title:" prefix, a fenced block, a whole sentence.
 * Keep the first non-empty line, strip the decoration, then cap words and characters.
 */
export function sanitizeGeneratedTitle(raw: string): string | null {
  if (!raw || !raw.trim()) return null
  const firstLine =
    raw
      .replace(/```[a-z]*/gi, ' ')
      .split(/\r?\n/)
      .map((line) => line.trim())
      .find((line) => line.length > 0) ?? ''
  const stripped = firstLine
    .replace(/^\s*(?:title|naslov)\s*[:\-–—]\s*/i, '')
    .replace(/[*_`#]+/g, '')
    .replace(/^["'“”„«»\s(\[{]+/, '')
    .replace(/["'“”„«»\s\])}.:;,!?]+$/, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (!stripped) return null
  const words = stripped.split(' ').filter(Boolean)
  let out = words.length > TITLE_MAX_WORDS ? words.slice(0, TITLE_MAX_WORDS).join(' ') : stripped
  if (out.length > TITLE_MAX_CHARS) out = out.slice(0, TITLE_MAX_CHARS).trim()
  return out || null
}

/**
 * True while the title is still machine-generated, so an upgrade may overwrite it.
 * A user rename (or an empty/placeholder title) decides this, never the clock.
 */
export function isAutoSessionTitle(title: string, messages: UiMessage[]): boolean {
  const current = (title || '').trim()
  // Same placeholder set the session store writes before a derived title lands.
  if (
    !current ||
    current === 'UNTITLED_SESSION' ||
    current === 'New chat' ||
    current === 'Unsaved'
  ) {
    return true
  }
  return current === deriveSessionTitle(messages).trim()
}

/**
 * One tool-free sub-agent call → a title, or null when there is nothing to name or the
 * model returned nothing usable. Throws only what `callSubAgentChat` throws; callers are
 * expected to swallow transport errors and keep the derived placeholder title.
 */
export async function generateSessionTitle(opts: {
  messages: UiMessage[]
  config: SubAgentConfig
  keys: SubAgentKeys
  signal?: AbortSignal
}): Promise<string | null> {
  if (!opts.config.model?.trim()) return null
  const seed = buildTitleSeedText(opts.messages)
  if (!seed) return null
  const raw = await callSubAgentChat({
    messages: [
      { role: 'system', content: TITLE_SYSTEM_PROMPT },
      { role: 'user', content: seed },
    ],
    config: opts.config,
    keys: opts.keys,
    signal: opts.signal,
    maxTokens: TITLE_MAX_OUTPUT_TOKENS,
  })
  return sanitizeGeneratedTitle(raw)
}
